CREATE OR REPLACE FUNCTION public.my_profile_access_ready() RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); BEGIN IF uid IS NULL THEN RETURN false; END IF; IF public.has_role(uid,'admin') THEN RETURN true; END IF; RETURN public.account_allowed(uid) AND EXISTS(SELECT 1 FROM public.profiles p JOIN public.account_programs a ON a.user_id=p.id JOIN auth.users u ON u.id=p.id WHERE p.id=uid AND length(trim(p.full_name))>0 AND length(trim(p.location))>0 AND p.phone ~ '^[6-9][0-9]{9}$' AND length(trim(a.occupation))>0 AND length(trim(a.category))>0 AND length(trim(a.member_kind))>0 AND u.phone_confirmed_at IS NOT NULL AND right(regexp_replace(u.phone,'\D','','g'),10)=p.phone); END $$;
REVOKE ALL ON FUNCTION public.my_profile_access_ready() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.my_profile_access_ready() TO authenticated;
CREATE OR REPLACE FUNCTION public.get_post_details(_post uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.posts; BEGIN IF NOT public.my_profile_access_ready() THEN RAISE EXCEPTION 'PROFILE_REQUIRED'; END IF; SELECT * INTO p FROM public.posts WHERE id=_post AND (user_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR (status='active' AND (visible_after IS NULL OR visible_after<=now()) AND (job_expires_at IS NULL OR job_expires_at>now()) AND public.account_allowed(user_id))); IF p.id IS NULL THEN RAISE EXCEPTION 'POST_UNAVAILABLE'; END IF; IF p.module='vehicle' AND NOT (public.has_paid_bell(auth.uid()) OR public.has_role(auth.uid(),'admin') OR p.user_id=auth.uid()) THEN RAISE EXCEPTION 'PAID_BELL_REQUIRED'; END IF; RETURN jsonb_build_object('description',p.description,'goods_type',p.goods_type,'capacity_tons',p.capacity_tons,'trip_date',p.trip_date,'vehicle_name',CASE WHEN p.module='vehicle' THEN p.vehicle_name ELSE NULL END,'vehicle_number',CASE WHEN p.module='vehicle' THEN p.vehicle_number ELSE NULL END,'driver_name',CASE WHEN p.module='vehicle' AND p.show_contact THEN p.driver_name ELSE NULL END,'contact_phone',CASE WHEN p.show_contact THEN p.contact_phone ELSE NULL END,'public_brand',CASE WHEN p.show_contact THEN p.public_brand ELSE '' END,'public_photo',CASE WHEN p.show_contact AND p.public_photo ~ '^https://' THEN p.public_photo ELSE '' END); END $$;